2	// Basic HTTP reachability check for an MRT-deployed environment.
3	// Run after a push to verify the deployment is serving traffic before marking it healthy.
4	//
5	// Usage: MRT_URL=https://your-env.net node scripts/smokeTest.js
6	// Exit code: 0 on 2xx/3xx, 1 on error or non-2xx/3xx response.
7	
8	const https = require('https');
9	const http = require('http');
10	
11	const targetUrl = process.env.MRT_URL;
12	
13	if (!targetUrl) {
14	  console.error('[FAIL] MRT_URL environment variable is required');
15	  process.exit(1);
16	}
17	
18	let parsedUrl;
19	try {
20	  parsedUrl = new URL(targetUrl);
21	} catch {
22	  console.error(`[FAIL] Invalid URL: ${targetUrl}`);
23	  process.exit(1);
24	}
25	
26	const client = parsedUrl.protocol === 'https:' ? https : http;
27	
28	const req = client.request(
29	  {
30	    hostname: parsedUrl.hostname,
31	    port: parsedUrl.port || (parsedUrl.protocol === 'https:' ? 443 : 80),
32	    path: parsedUrl.pathname || '/',
33	    method: 'GET',
34	    timeout: 10000,
35	    headers: { 'User-Agent': 'zimm-smoke-test/1.0' },
36	  },
37	  (res) => {
38	    const { statusCode } = res;
39	    res.resume();
40	    if (statusCode >= 200 && statusCode < 400) {
41	      console.log(`[PASS] ${targetUrl} — HTTP ${statusCode}`);
42	      process.exit(0);
43	    } else {
44	      console.error(`[FAIL] ${targetUrl} — HTTP ${statusCode}`);
45	      process.exit(1);
46	    }
47	  },
48	);
49	
50	req.on('error', (err) => {
51	  console.error(`[FAIL] ${targetUrl} — ${err.message}`);
52	  process.exit(1);
53	});
54	
55	req.on('timeout', () => {
56	  console.error(`[FAIL] ${targetUrl} — request timed out after 10s`);
57	  req.destroy();
58	  process.exit(1);
59	});
60	
61	req.end();
